<script setup>
import draggable from'vuedraggable';const props=defineProps({modelValue:{type:Array,default:()=>[]},disabled:Boolean});const emit=defineEmits(['update:modelValue']);function add(){emit('update:modelValue',[...props.modelValue,{key:`field_${Date.now()}`,label:'New field',description:'',type:'text',required:false,default_value:null,options:[],section:''}])}function remove(i){const copy=[...props.modelValue];copy.splice(i,1);emit('update:modelValue',copy)}function options(field,text){field.options=text.split('\n').filter(Boolean).map(line=>{const[label,value]=line.split('|');return{label:label.trim(),value:(value||label).trim()}})}
</script>
<template><div><draggable :model-value="modelValue" item-key="key" handle=".drag-handle" :disabled="disabled" @update:model-value="emit('update:modelValue',$event)"><template #item="{element,index}"><article class="mb-3 border border-dark bg-light p-4"><div class="flex justify-between"><button type="button" class="drag-handle" aria-label="Drag field">☰</button><button v-if="!disabled" type="button" @click="remove(index)">Remove</button></div><div class="mt-3 grid gap-3 sm:grid-cols-2"><div class="admin-field"><label>Label</label><input v-model="element.label" :disabled="disabled"></div><div class="admin-field"><label>Stable key</label><input v-model="element.key" :disabled="disabled||Boolean(element.id)"></div><div class="admin-field"><label>Type</label><select v-model="element.type" :disabled="disabled"><option v-for="type in ['text','textarea','number','date','checkbox','select','multi_select','radio']" :key="type">{{type}}</option></select></div><div class="admin-field"><label>Section</label><input v-model="element.section" :disabled="disabled"></div><div class="admin-field sm:col-span-2"><label>Help text</label><input v-model="element.description" :disabled="disabled"></div><div v-if="['select','multi_select','radio'].includes(element.type)" class="admin-field sm:col-span-2"><label>Options: Label|value, one per line</label><textarea :value="(element.options||[]).map(o=>`${o.label}|${o.value}`).join('\n')" :disabled="disabled" @input="options(element,$event.target.value)"></textarea></div><label><input v-model="element.required" type="checkbox" :disabled="disabled"> Required</label></div></article></template></draggable><button v-if="!disabled" type="button" class="admin-button" @click="add">Add field</button></div></template>